{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * SPDX-License-Identifier: BSD-3-Clause
 *
 * UpsampleTrilinear3dBackward AscendC kernel
 *
 * Computes the gradient of trilinear 3D upsampling:
 *   For each output position (d_out, h_out, w_out):
 *     - Map to source coordinates using scale factors
 *     - Compute 8 trilinear interpolation weights
 *     - Scatter-add gradient * weight to 8 corner input positions
 */

#include "kernel_operator.h"

constexpr int64_t BUFFER_NUM = 2;

template <typename T>
class KernelUpsampleTrilinear3dBackward {
public:
    __aicore__ inline KernelUpsampleTrilinear3dBackward() {}
    __aicore__ inline void Init(
        AscendC::GlobalTensor<T> gradOutputGm,
        AscendC::GlobalTensor<T> gradInputGm,
        AscendC::GlobalTensor<float> scaleFactorsGm,
        int64_t oD, int64_t oH, int64_t oW,
        int64_t iD, int64_t iH, int64_t iW,
        int64_t totalOutputSpatial,
        int64_t alignCorners,
        int64_t tileOH, int64_t tileOW,
        AscendC::TPipe *pipe)
    {
        pipe_ = pipe;
        gradOutputGm_ = gradOutputGm;
        gradInputGm_ = gradInputGm;
        scaleFactorsGm_ = scaleFactorsGm;
        oD_ = oD;
        oH_ = oH;
        oW_ = oW;
        iD_ = iD;
        iH_ = iH;
        iW_ = iW;
        totalOutputSpatial_ = totalOutputSpatial;
        alignCorners_ = alignCorners;
        tileOH_ = tileOH;
        tileOW_ = tileOW;
    }

    __aicore__ inline void Process()
    {
        // Compute the (n, c) pair assigned to this core
        int64_t ncIdx = AscendC::GetBlockIdx();
        int64_t n = ncIdx / totalChannels_;
        int64_t c = ncIdx % totalChannels_;
        // NOTE: totalChannels_ will be set by the host tiling via a reserved field or computed
        // For now, we use a simple approach: each core processes one (n,c) pair
        // totalChannels_ is determined from the tiling struct

        // Load scale factors: [scale_d, scale_h, scale_w, scale_d_nonalign, scale_h_nonalign, scale_w_nonalign]
        float scaleFactors[6];
        AscendC::DataCopyExtParams copyScaleParams = {1, 6 * sizeof(float), 0, 0, 0};
        AscendC::LocalTensor<float> scaleLocal = inQueueScale_.AllocTensor<float>();
        AscendC::DataCopy(scaleLocal, scaleFactorsGm_, copyScaleParams);
        inQueueScale_.EnQue(scaleLocal);
        AscendC::LocalTensor<float> scaleDeque = inQueueScale_.DeQue<float>();
        // Read scale factors by index
        float scaleD = scaleDeque.GetValue(0);
        float scaleH = scaleDeque.GetValue(1);
        float scaleW = scaleDeque.GetValue(2);
        float scaleDNonAlign = scaleDeque.GetValue(3);
        float scaleHNonAlign = scaleDeque.GetValue(4);
        float scaleWNonAlign = scaleDeque.GetValue(5);
        inQueueScale_.FreeTensor(scaleDeque);

        // Initialize input gradient for this (n, c) slice to zeros
        int64_t inputSliceSize = iD_ * iH_ * iW_;
        int64_t inputGmOffset = ((n * totalChannels_ + c) * inputSliceSize);

        // Use UB as local accumulation buffer for small input grids
        // For larger grids, we'd need GM workspace; for now, we accumulate directly
        // by loading -> adding -> storing back (scatter-add via GM read-modify-write)

        // Iterate over output spatial grid
        // For each d_out, process (h_out, w_out) in tiles
        for (int64_t dOut = 0; dOut < oD_; ++dOut) {
            // Compute depth interpolation parameters (scalar)
            float dSrc;
            if (alignCorners_) {
                dSrc = scaleD * float(dOut);
            } else {
                dSrc = scaleDNonAlign * (float(dOut) + 0.5f) - 0.5f;
                if (dSrc < 0.0f) dSrc = 0.0f;
            }
            int64_t d0 = int64_t(dSrc);
            int64_t d1 = d0 + 1;
            if (d1 >= iD_) d1 = iD_ - 1;
            if (d0 >= iD_) d0 = iD_ - 1;
            if (d0 < 0) d0 = 0;
            float ld = (d0 != d1) ? (dSrc - float(d0)) : 0.0f;

            // Tile over (h_out, w_out)
            int64_t numHTiles = (oH_ + tileOH_ - 1) / tileOH_;
            int64_t numWTiles = (oW_ + tileOW_ - 1) / tileOW_;

            for (int64_t ht = 0; ht < numHTiles; ++ht) {
                int64_t hStart = ht * tileOH_;
                int64_t hEnd = (hStart + tileOH_ < oH_) ? (hStart + tileOH_) : oH_;

                for (int64_t wt = 0; wt < numWTiles; ++wt) {
                    int64_t wStart = wt * tileOW_;
                    int64_t wEnd = (wStart + tileOW_ < oW_) ? (wStart + tileOW_) : oW_;

                    // Process this tile
                    ProcessTile2D(dOut, hStart, hEnd, wStart, wEnd,
                                  d0, d1, ld,
                                  scaleH, scaleW,
                                  scaleHNonAlign, scaleWNonAlign,
                                  n, c, inputGmOffset);
                }
            }
        }
    }

private:
    __aicore__ inline void ProcessTile2D(
        int64_t dOut, int64_t hStart, int64_t hEnd, int64_t wStart, int64_t wEnd,
        int64_t d0, int64_t d1, float ld,
        float scaleH, float scaleW,
        float scaleHNonAlign, float scaleWNonAlign,
        int64_t n, int64_t c, int64_t inputGmOffset)
    {
        int64_t tileH = hEnd - hStart;
        int64_t tileW = wEnd - wStart;
        int64_t tileSize = tileH * tileW;

        // Load the output gradient tile from GM to UB
        int64_t gradOutputBase = ((n * totalChannels_ + c) * oD_ + dOut) * oH_ * oW_;
        AscendC::LocalTensor<T> gradTile = inQueue_.AllocTensor<T>();
        AscendC::DataCopyExtParams copyParams = {
            static_cast<uint16_t>(tileH * tileW),
            static_cast<uint16_t>(tileW * sizeof(T)),
            0, 0, 0
        };
        // We need a 2D DataCopy for the tile
        // For simplicity, load row by row
        AscendC::DataCopyParams rowCopyParams;
        rowCopyParams.blockCount = 1;
        rowCopyParams.blockLen = static_cast<uint16_t>(tileW * sizeof(T));
        rowCopyParams.srcStride = static_cast<uint16_t>(oW_ * sizeof(T));
        rowCopyParams.dstStride = 0;

        // Load tile row by row using DataCopyPad for alignment safety
        AscendC::DataCopyPadExtParams<T> padParams = {false, 0, 0, 0};

        for (int64_t hr = 0; hr < tileH; ++hr) {
            int64_t hOut = hStart + hr;
            int64_t gmRowOffset = gradOutputBase + hOut * oW_ + wStart;
            AscendC::LocalTensor<T> rowLocal = gradTile[hr * tileW];
            AscendC::DataCopyPad(
                rowLocal,
                gradOutputGm_[gmRowOffset],
                AscendC::DataCopyExtParams{1, static_cast<uint16_t>(tileW * sizeof(T)), 0, 0, 0},
                padParams);
        }
        inQueue_.EnQue(gradTile);
        AscendC::LocalTensor<T> gradDeque = inQueue_.DeQue<T>();

        // Create FP32 accumulation buffers for computation
        AscendC::LocalTensor<float> gradFp32 = calcBuf_.Get<float>(tileSize);
        AscendC::LocalTensor<float> weightBuf = calcBuf2_.Get<float>(tileSize * 4);

        // Cast to FP32 for accumulation
        if constexpr (sizeof(T) == sizeof(float)) {
            AscendC::DataCopy(gradFp32, gradDeque, tileSize);
        } else {
            AscendC::Cast(gradFp32, gradDeque, AscendC::RoundMode::CAST_NONE, tileSize);
        }

        // Compute source coordinates and weights for each position in the 2D tile
        // For each position, compute h_src, w_src, h0, h1, w0, w1, lh, lw
        // Then compute 8 trilinear weights and scatter-add

        for (int64_t hr = 0; hr < tileH; ++hr) {
            int64_t hOut = hStart + hr;
            float hSrc;
            if (alignCorners_) {
                hSrc = scaleH * float(hOut);
            } else {
                hSrc = scaleHNonAlign * (float(hOut) + 0.5f) - 0.5f;
                if (hSrc < 0.0f) hSrc = 0.0f;
            }
            int64_t h0 = int64_t(hSrc);
            int64_t h1 = h0 + 1;
            if (h1 >= iH_) h1 = iH_ - 1;
            if (h0 >= iH_) h0 = iH_ - 1;
            if (h0 < 0) h0 = 0;
            float lh = (h0 != h1) ? (hSrc - float(h0)) : 0.0f;

            for (int64_t wr = 0; wr < tileW; ++wr) {
                int64_t wOut = wStart + wr;
                float wSrc;
                if (alignCorners_) {
                    wSrc = scaleW * float(wOut);
                } else {
                    wSrc = scaleWNonAlign * (float(wOut) + 0.5f) - 0.5f;
                    if (wSrc < 0.0f) wSrc = 0.0f;
                }
                int64_t w0 = int64_t(wSrc);
                int64_t w1 = w0 + 1;
                if (w1 >= iW_) w1 = iW_ - 1;
                if (w0 >= iW_) w0 = iW_ - 1;
                if (w0 < 0) w0 = 0;
                float lw = (w0 != w1) ? (wSrc - float(w0)) : 0.0f;

                // Compute 8 trilinear weights
                float hld = 1.0f - ld;
                float hlh = 1.0f - lh;
                float hlw = 1.0f - lw;
                float w000 = hld * hlh * hlw;
                float w001 = hld * hlh * lw;
                float w010 = hld * lh * hlw;
                float w011 = hld * lh * lw;
                float w100 = ld * hlh * hlw;
                float w101 = ld * hlh * lw;
                float w110 = ld * lh * hlw;
                float w111 = ld * lh * lw;

                // Get the gradient value for this output position
                float gradVal = gradFp32.GetValue(hr * tileW + wr);

                // Scatter-add to 8 corner positions in the output (direct GM read-modify-write)
                ScatterAddCorner(inputGmOffset, d0, h0, w0, gradVal * w000);
                ScatterAddCorner(inputGmOffset, d0, h0, w1, gradVal * w001);
                ScatterAddCorner(inputGmOffset, d0, h1, w0, gradVal * w010);
                ScatterAddCorner(inputGmOffset, d0, h1, w1, gradVal * w011);
                ScatterAddCorner(inputGmOffset, d1, h0, w0, gradVal * w100);
                ScatterAddCorner(inputGmOffset, d1, h0, w1, gradVal * w101);
                ScatterAddCorner(inputGmOffset, d1, h1, w0, gradVal * w110);
                ScatterAddCorner(inputGmOffset, d1, h1, w1, gradVal * w111);
            }
        }

        inQueue_.FreeTensor(gradDeque);
    }

    __aicore__ inline void ScatterAddCorner(
        int64_t inputGmOffset, int64_t d, int64_t h, int64_t w, float value)
    {
        // Read current value from GM, add, write back
        // This uses a UB-based read-modify-write approach
        int64_t elementIdx = inputGmOffset + d * iH_ * iW_ + h * iW_ + w;

        // Allocate temp buffer for the read-modify-write
        AscendC::LocalTensor<float> tmpLocal = scatterBuf_.Get<float>(1);
        AscendC::LocalTensor<T> tmpLocalOut = scatterBuf_.Get<T>(1);

        // Read current value
        AscendC::DataCopyExtParams readParams = {1, sizeof(T), 0, 0, 0};
        AscendC::DataCopy(tmpLocalOut, gradInputGm_[elementIdx], readParams);

        // Cast to float if needed
        float currentVal;
        if constexpr (sizeof(T) == sizeof(float)) {
            currentVal = tmpLocalOut.GetValue(0);
        } else {
            AscendC::Cast(tmpLocal, tmpLocalOut, AscendC::RoundMode::CAST_NONE, 1);
            currentVal = tmpLocal.GetValue(0);
        }

        // Add and write back
        currentVal += value;
        tmpLocal.SetValue(0, currentVal);

        // Cast back if needed
        if constexpr (sizeof(T) == sizeof(float)) {
            AscendC::DataCopy(gradInputGm_[elementIdx], tmpLocal, readParams);
        } else {
            AscendC::Cast(tmpLocalOut, tmpLocal, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::DataCopy(gradInputGm_[elementIdx], tmpLocalOut, readParams);
        }
    }

private:
    AscendC::TPipe *pipe_;
    AscendC::GlobalTensor<T> gradOutputGm_;
    AscendC::GlobalTensor<T> gradInputGm_;
    AscendC::GlobalTensor<float> scaleFactorsGm_;
    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inQueueScale_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> calcBuf_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> calcBuf2_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> scatterBuf_;

    int64_t oD_, oH_, oW_, iD_, iH_, iW_;
    int64_t totalChannels_;
    int64_t totalOutputSpatial_;
    int64_t alignCorners_;
    int64_t tileOH_, tileOW_;
};

extern "C" __global__ __aicore__ void upsample_trilinear3d_backward_kernel(
    AscendC::GlobalTensor<float16_t> gradOutputGm,
    AscendC::GlobalTensor<float16_t> gradInputGm,
    AscendC::GlobalTensor<float> scaleFactorsGm,
    AscendC::GlobalTensor<int64_t> tilingGm)
{
    // Read tiling parameters from the tiling tensor
    // tilingGm layout: [oD, oH, oW, iD, iH, iW, totalChannels, alignCorners, tileOH, tileOW]

    // NOTE: For this implementation, tiling parameters are passes as compile-time-like
    // values in the tiling struct. We instantiate the appropriate kernel based on dtype.

    // Placeholder - actual implementation depends on the exact AscendC API version
    // and needs the full tiling struct + dtype dispatch.
}
