123	template <typename F>
124	__aicore__ inline void ProcessLoop(
125	    F &&processRowFn,
126	    int32_t tasksPerCore, int32_t M, int32_t blockM, int32_t subBlockRows_)
127	{
128	    if ASCEND_IS_AIV {
129	        const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();
130	        const int subBlockIdx = AscendC::GetSubBlockIdx();
131	
132	        for (int localIdx = 0; localIdx < tasksPerCore; ++localIdx) {
133	            const int bx = coreIdx * tasksPerCore + localIdx;
134	            if (bx >= BlockCountHelper(M, blockM)) {
135	                continue;
136	            }
137	
138	            for (int row = 0; row < subBlockRows_; ++row) {
139	                const int rowIdx = bx * blockM + subBlockIdx * subBlockRows_ + row;
140	                if (rowIdx < M) {
141	                    processRowFn(rowIdx);
142	                }
143	            }
144	        }
145	    }
146	}
