{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * SPDX-License-Identifier: BSD-3-Clause
 *
 * UpsampleTrilinear3dBackward AscendC kernel
 *
 * Computes the gradient of trilinear 3D upsampling:
 *   For each output grid position (d_out, h_out, w_out):
 *     - Maps to source coordinates using scale factors
 *     - Computes 8 trilinear corner weights
 *     - Scatter-adds weighted gradient to 8 input corner positions
 *
 * Parallelism: Each core handles one or more (n,c) pairs.
 * The output spatial grid is tiled in 2D (h_out, w_out) per depth slice.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelUpsampleTrilinear3dBackward {
public:
    __aicore__ inline KernelUpsampleTrilinear3dBackward() {}
    __aicore__ inline void Init(
        GM_ADDR gradOutput, GM_ADDR gradInput,
        float scaleD, float scaleH, float scaleW,
        float scaleDNonAlign, float scaleHNonAlign, float scaleWNonAlign,
        int64_t N, int64_t C, int64_t oD, int64_t oH, int64_t oW,
        int64_t iD, int64_t iH, int64_t iW,
        int64_t totalWorkItems, int64_t tasksPerCore,
        int64_t alignCorners,
        int64_t tileOH, int64_t tileOW)
    {
        scaleD_ = scaleD;
        scaleH_ = scaleH;
        scaleW_ = scaleW;
        scaleDNonAlign_ = scaleDNonAlign;
        scaleHNonAlign_ = scaleHNonAlign;
        scaleWNonAlign_ = scaleWNonAlign;
        N_ = N;
        C_ = C;
        oD_ = oD;
        oH_ = oH;
        oW_ = oW;
        iD_ = iD;
        iH_ = iH;
        iW_ = iW;
        totalWorkItems_ = totalWorkItems;
        tasksPerCore_ = tasksPerCore;
        alignCorners_ = alignCorners;
        tileOH_ = tileOH;
        tileOW_ = tileOW;

        uint64_t gradOutputSize = static_cast<uint64_t>(N) * C * oD * oH * oW;
        uint64_t gradInputSize = static_cast<uint64_t>(N) * C * iD * iH * iW;
        gradOutputGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(gradOutput), gradOutputSize);
        gradInputGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(gradInput), gradInputSize);

        // Compute max tile size in elements
        int64_t maxTileSize = tileOH_ * tileOW_;
        int64_t castBufSize = maxTileSize * 2;  // room for cast + compute buffers

        pipe_.InitBuffer(inQueue_, BUFFER_NUM, maxTileSize * sizeof(T));
        pipe_.InitBuffer(castBuf_, castBufSize * sizeof(float));
        pipe_.InitBuffer(scatterBuf_, 2 * sizeof(float));  // for GM read-modify-write
        pipe_.InitBuffer(scatterBufT_, 2 * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t coreIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
        int64_t ncStart = coreIdx * tasksPerCore_;
        int64_t ncEnd = ncStart + tasksPerCore_;
        if (ncEnd > totalWorkItems_) {
            ncEnd = totalWorkItems_;
        }

        for (int64_t nc = ncStart; nc < ncEnd; ++nc) {
            int64_t n = nc / C_;
            int64_t c = nc % C_;
            ProcessSlice(n, c);
        }
    }

private:
    __aicore__ inline void ProcessSlice(int64_t n, int64_t c)
    {
        int64_t gradOutputSliceBase = (n * C_ + c) * oD_ * oH_ * oW_;
        int64_t gradInputSliceBase = (n * C_ + c) * iD_ * iH_ * iW_;

        for (int64_t dOut = 0; dOut < oD_; ++dOut) {
            float dSrc;
            if (alignCorners_) {
                dSrc = scaleD_ * static_cast<float>(dOut);
            } else {
                dSrc = scaleDNonAlign_ * (static_cast<float>(dOut) + 0.5f) - 0.5f;
                if (dSrc < 0.0f) { dSrc = 0.0f; }
            }
            int64_t d0 = static_cast<int64_t>(dSrc);
            int64_t d1 = d0 + 1;
            if (d1 >= iD_) { d1 = iD_ - 1; }
            if (d0 >= iD_) { d0 = iD_ - 1; }
            if (d0 < 0) { d0 = 0; }
            float ld = (d0 != d1) ? (dSrc - static_cast<float>(d0)) : 0.0f;

            int64_t numHTiles = (oH_ + tileOH_ - 1) / tileOH_;
            int64_t numWTiles = (oW_ + tileOW_ - 1) / tileOW_;

            for (int64_t ht = 0; ht < numHTiles; ++ht) {
                int64_t hStart = ht * tileOH_;
                int64_t hEnd = (hStart + tileOH_ < oH_) ? (hStart + tileOH_) : oH_;
                int64_t curTileH = hEnd - hStart;

                for (int64_t wt = 0; wt < numWTiles; ++wt) {
                    int64_t wStart = wt * tileOW_;
                    int64_t wEnd = (wStart + tileOW_ < oW_) ? (wStart + tileOW_) : oW_;
                    int64_t curTileW = wEnd - wStart;

                    ProcessTile(gradOutputSliceBase + dOut * oH_ * oW_,
                                gradInputSliceBase,
                                dOut, hStart, hEnd, wStart, wEnd,
                                d0, d1, ld);
                }
            }
        }
    }

    __aicore__ inline void ProcessTile(
        int64_t gradOutputBase, int64_t gradInputBase,
        int64_t dOut, int64_t hStart, int64_t hEnd, int64_t wStart, int64_t wEnd,
        int64_t d0, int64_t d1, float ld)
    {
        int64_t tileH = hEnd - hStart;
        int64_t tileW = wEnd - wStart;
        int64_t tileSize = tileH * tileW;

        // CopyIn: load gradOutput tile row by row into UB
        AscendC::LocalTensor<T> gradTile = inQueue_.AllocTensor<T>();
        AscendC::DataCopyPadExtParams<T> padParams = {false, 0, 0, 0};

        for (int64_t hr = 0; hr < tileH; ++hr) {
            int64_t hOut = hStart + hr;
            int64_t gmOffset = gradOutputBase + hOut * oW_ + wStart;
            AscendC::DataCopyExtParams copyParams = {
                1, static_cast<uint16_t>(tileW * sizeof(T)), 0, 0, 0
            };
            AscendC::DataCopyPad(
                gradTile[hr * tileW],
                gradOutputGm_[gmOffset],
                copyParams, padParams);
        }
        inQueue_.EnQue(gradTile);
        AscendC::LocalTensor<T> gradDeque = inQueue_.DeQue<T>();

        // Cast to FP32 for computation
        AscendC::LocalTensor<float> gradFp32;
        if constexpr (std::is_same_v<T, float>) {
            gradFp32 = gradDeque.template ReinterpretCast<float>();
        } else {
            gradFp32 = castBuf_.Get<float>(tileSize);
            AscendC::Cast(gradFp32, gradDeque, AscendC::RoundMode::CAST_NONE, tileSize);
        }

        // Compute per-position: source coords, weights, scatter-add
        AscendC::LocalTensor<float> scatterFp32 = scatterBuf_.Get<float>(1);
        AscendC::LocalTensor<T> scatterT = scatterBufT_.Get<T>(1);

        AscendC::DataCopyExtParams elemCopyParams = {1, sizeof(T), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> elemPadParams = {false, 0, 0, 0};

        for (int64_t hr = 0; hr < tileH; ++hr) {
            int64_t hOut = hStart + hr;

            float hSrc;
            if (alignCorners_) {
                hSrc = scaleH_ * static_cast<float>(hOut);
            } else {
                hSrc = scaleHNonAlign_ * (static_cast<float>(hOut) + 0.5f) - 0.5f;
                if (hSrc < 0.0f) { hSrc = 0.0f; }
            }
            int64_t h0 = static_cast<int64_t>(hSrc);
            int64_t h1 = h0 + 1;
            if (h1 >= iH_) { h1 = iH_ - 1; }
            if (h0 >= iH_) { h0 = iH_ - 1; }
            if (h0 < 0) { h0 = 0; }
            float lh = (h0 != h1) ? (hSrc - static_cast<float>(h0)) : 0.0f;

            float hld = 1.0f - ld;
            float hlh = 1.0f - lh;

            for (int64_t wr = 0; wr < tileW; ++wr) {
                int64_t wOut = wStart + wr;

                float wSrc;
                if (alignCorners_) {
                    wSrc = scaleW_ * static_cast<float>(wOut);
                } else {
                    wSrc = scaleWNonAlign_ * (static_cast<float>(wOut) + 0.5f) - 0.5f;
                    if (wSrc < 0.0f) { wSrc = 0.0f; }
                }
                int64_t w0 = static_cast<int64_t>(wSrc);
                int64_t w1 = w0 + 1;
                if (w1 >= iW_) { w1 = iW_ - 1; }
                if (w0 >= iW_) { w0 = iW_ - 1; }
                if (w0 < 0) { w0 = 0; }
                float lw = (w0 != w1) ? (wSrc - static_cast<float>(w0)) : 0.0f;

                // 8 weights
                float hlw = 1.0f - lw;
                float w000 = hld * hlh * hlw;
                float w001 = hld * hlh * lw;
                float w010 = hld * lh * hlw;
                float w011 = hld * lh * lw;
                float w100 = ld * hlh * hlw;
                float w101 = ld * hlh * lw;
                float w110 = ld * lh * hlw;
                float w111 = ld * lh * lw;

                float gradVal = gradFp32.GetValue(hr * tileW + wr);

                // Scatter-add to 8 corners (GM read-modify-write per corner)
                ScatterAdd(gradInputBase, d0, h0, w0, gradVal * w000, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d0, h0, w1, gradVal * w001, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d0, h1, w0, gradVal * w010, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d0, h1, w1, gradVal * w011, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d1, h0, w0, gradVal * w100, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d1, h0, w1, gradVal * w101, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d1, h1, w0, gradVal * w110, scatterFp32, scatterT, elemCopyParams, elemPadParams);
                ScatterAdd(gradInputBase, d1, h1, w1, gradVal * w111, scatterFp32, scatterT, elemCopyParams, elemPadParams);
            }
        }

        inQueue_.FreeTensor(gradDeque);
    }

    __aicore__ inline void ScatterAdd(
        int64_t gradInputBase, int64_t d, int64_t h, int64_t w, float value,
        AscendC::LocalTensor<float> &scatterFp32,
        AscendC::LocalTensor<T> &scatterT,
        AscendC::DataCopyExtParams &elemCopyParams,
        AscendC::DataCopyPadExtParams<T> &elemPadParams)
    {
        if (value == 0.0f) { return; }

        int64_t offset = gradInputBase + d * iH_ * iW_ + h * iW_ + w;

        // Read current value from GM
        AscendC::DataCopyPad(scatterT, gradInputGm_[offset], elemCopyParams, elemPadParams);

        // Cast to float, add, cast back
        float currentVal;
        if constexpr (std::is_same_v<T, float>) {
            currentVal = scatterT.GetValue(0);
        } else {
            AscendC::Cast(scatterFp32, scatterT, AscendC::RoundMode::CAST_NONE, 1);
            currentVal = scatterFp32.GetValue(0);
        }

        currentVal += value;
        scatterFp32.SetValue(0, currentVal);

        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopyPad(gradInputGm_[offset], scatterFp32, elemCopyParams);
        } else {
            AscendC::Cast(scatterT, scatterFp32, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::DataCopyPad(gradInputGm_[offset], scatterT, elemCopyParams);
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> gradOutputGm_;
    AscendC::GlobalTensor<T> gradInputGm_;

    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueue_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> castBuf_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> scatterBuf_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> scatterBufT_;

    float scaleD_, scaleH_, scaleW_;
    float scaleDNonAlign_, scaleHNonAlign_, scaleWNonAlign_;
    int64_t N_, C_, oD_, oH_, oW_, iD_, iH_, iW_;
    int64_t totalWorkItems_, tasksPerCore_;
    int64_t alignCorners_;
    int64_t tileOH_, tileOW_;
};

// Dtype dispatch helper
template <template <typename> class Kernel, typename... ExtraArgs>
__aicore__ inline void DispatchUpsampleTrilinear3dBackward(
    GM_ADDR gradOutput, GM_ADDR gradInput,
    float scaleD, float scaleH, float scaleW,
    float scaleDNonAlign, float scaleHNonAlign, float scaleWNonAlign,
    int64_t N, int64_t C, int64_t oD, int64_t oH, int64_t oW,
    int64_t iD, int64_t iH, int64_t iW,
    int64_t totalWorkItems, int64_t tasksPerCore,
    int64_t alignCorners,
    int64_t tileOH, int64_t tileOW,
    int64_t dtypeFlag)
{
    if (dtypeFlag == 0) {
        Kernel<float> kernel;
        kernel.Init(gradOutput, gradInput,
                    scaleD, scaleH, scaleW,
                    scaleDNonAlign, scaleHNonAlign, scaleWNonAlign,
                    N, C, oD, oH, oW, iD, iH, iW,
                    totalWorkItems, tasksPerCore, alignCorners,
                    tileOH, tileOW);
        kernel.Process();
    } else if (dtypeFlag == 1) {
        Kernel<half> kernel;
        kernel.Init(gradOutput, gradInput,
                    scaleD, scaleH, scaleW,
                    scaleDNonAlign, scaleHNonAlign, scaleWNonAlign,
                    N, C, oD, oH, oW, iD, iH, iW,
                    totalWorkItems, tasksPerCore, alignCorners,
                    tileOH, tileOW);
        kernel.Process();
    } else {
        Kernel<bfloat16_t> kernel;
        kernel.Init(gradOutput, gradInput,
                    scaleD, scaleH, scaleW,
                    scaleDNonAlign, scaleHNonAlign, scaleWNonAlign,
                    N, C, oD, oH, oW, iD, iH, iW,
                    totalWorkItems, tasksPerCore, alignCorners,
                    tileOH, tileOW);
        kernel.Process();
    }
}

extern "C" __global__ __aicore__ void upsample_trilinear3d_backward(
    GM_ADDR gradOutput, GM_ADDR gradInput,
    float scaleD, float scaleH, float scaleW,
    float scaleDNonAlign, float scaleHNonAlign, float scaleWNonAlign,
    int64_t N, int64_t C, int64_t oD, int64_t oH, int64_t oW,
    int64_t iD, int64_t iH, int64_t iW,
    int64_t totalWorkItems, int64_t tasksPerCore,
    int64_t alignCorners,
    int64_t tileOH, int64_t tileOW,
    int64_t dtypeFlag)
{
    DispatchUpsampleTrilinear3dBackward<KernelUpsampleTrilinear3dBackward>(
        gradOutput, gradInput,
        scaleD, scaleH, scaleW,
        scaleDNonAlign, scaleHNonAlign, scaleWNonAlign,
        N, C, oD, oH, oW, iD, iH, iW,
        totalWorkItems, tasksPerCore, alignCorners,
        tileOH, tileOW, dtypeFlag);
}
