{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 * SPDX-License-Identifier: BSD-3-Clause
 *
 * UpsampleTrilinear3dBackward AscendC kernel
 *
 * Computes the gradient of trilinear 3D upsampling.
 * For each output position (d_out, h_out, w_out) in the spatial grid,
 * maps to source coordinates, computes 8 trilinear weights, and
 * scatter-adds the weighted gradient to 8 input corner positions.
 *
 * Each core handles one or more (n,c) pairs.
 */

#include "kernel_operator.h"

template <typename T>
class KernelUpsampleTrilinear3dBackward {
public:
    __aicore__ inline KernelUpsampleTrilinear3dBackward() {}
    __aicore__ inline void Init(
        GM_ADDR gradOutput, GM_ADDR gradInput,
        float scaleD, float scaleH, float scaleW,
        float scaleDNonAlign, float scaleHNonAlign, float scaleWNonAlign,
        int64_t N, int64_t C, int64_t oD, int64_t oH, int64_t oW,
        int64_t iD, int64_t iH, int64_t iW,
        int64_t totalWorkItems, int64_t tasksPerCore,
        int64_t alignCorners)
    {
        scaleD_ = scaleD;
        scaleH_ = scaleH;
        scaleW_ = scaleW;
        scaleDNonAlign_ = scaleDNonAlign;
        scaleHNonAlign_ = scaleHNonAlign;
        scaleWNonAlign_ = scaleWNonAlign;
        N_ = N;
        C_ = C;
        oD_ = oD;
        oH_ = oH;
        oW_ = oW;
        iD_ = iD;
        iH_ = iH;
        iW_ = iW;
        totalWorkItems_ = totalWorkItems;
        tasksPerCore_ = tasksPerCore;
        alignCorners_ = alignCorners;

        uint64_t gradOutputSize = static_cast<uint64_t>(N) * C * oD * oH * oW;
        uint64_t gradInputSize = static_cast<uint64_t>(N) * C * iD * iH * iW;
        gradOutputGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(gradOutput), gradOutputSize);
        gradInputGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(gradInput), gradInputSize);

        // Minimal UB buffers: single element for GM read/write
        pipe_.InitBuffer(inQueue_, 2, sizeof(T));
        pipe_.InitBuffer(scatterFp32Buf_, sizeof(float));
        pipe_.InitBuffer(scatterTBuf_, sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t coreIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
        int64_t ncStart = coreIdx * tasksPerCore_;
        int64_t ncEnd = ncStart + tasksPerCore_;
        if (ncEnd > totalWorkItems_) {
            ncEnd = totalWorkItems_;
        }

        for (int64_t nc = ncStart; nc < ncEnd; ++nc) {
            int64_t n = nc / C_;
            int64_t c = nc % C_;
            ProcessSlice(n, c);
        }
    }

private:
    __aicore__ inline void ProcessSlice(int64_t n, int64_t c)
    {
        int64_t gradOutputSliceBase = (n * C_ + c) * oD_ * oH_ * oW_;
        int64_t gradInputSliceBase = (n * C_ + c) * iD_ * iH_ * iW_;

        for (int64_t dOut = 0; dOut < oD_; ++dOut) {
            float dSrc;
            if (alignCorners_) {
                dSrc = scaleD_ * static_cast<float>(dOut);
            } else {
                dSrc = scaleDNonAlign_ * (static_cast<float>(dOut) + 0.5f) - 0.5f;
                if (dSrc < 0.0f) { dSrc = 0.0f; }
            }
            int64_t d0 = static_cast<int64_t>(dSrc);
            int64_t d1 = d0 + 1;
            if (d1 >= iD_) { d1 = iD_ - 1; }
            if (d0 >= iD_) { d0 = iD_ - 1; }
            if (d0 < 0) { d0 = 0; }
            float ld = (d0 != d1) ? (dSrc - static_cast<float>(d0)) : 0.0f;

            float hld = 1.0f - ld;

            int64_t gradOutputDepthBase = gradOutputSliceBase + dOut * oH_ * oW_;

            for (int64_t hOut = 0; hOut < oH_; ++hOut) {
                float hSrc;
                if (alignCorners_) {
                    hSrc = scaleH_ * static_cast<float>(hOut);
                } else {
                    hSrc = scaleHNonAlign_ * (static_cast<float>(hOut) + 0.5f) - 0.5f;
                    if (hSrc < 0.0f) { hSrc = 0.0f; }
                }
                int64_t h0 = static_cast<int64_t>(hSrc);
                int64_t h1 = h0 + 1;
                if (h1 >= iH_) { h1 = iH_ - 1; }
                if (h0 >= iH_) { h0 = iH_ - 1; }
                if (h0 < 0) { h0 = 0; }
                float lh = (h0 != h1) ? (hSrc - static_cast<float>(h0)) : 0.0f;

                float hlh = 1.0f - lh;
                float wD0H0 = hld * hlh;
                float wD0H1 = hld * lh;
                float wD1H0 = ld * hlh;
                float wD1H1 = ld * lh;

                int64_t gradOutputRowBase = gradOutputDepthBase + hOut * oW_;

                for (int64_t wOut = 0; wOut < oW_; ++wOut) {
                    float wSrc;
                    if (alignCorners_) {
                        wSrc = scaleW_ * static_cast<float>(wOut);
                    } else {
                        wSrc = scaleWNonAlign_ * (static_cast<float>(wOut) + 0.5f) - 0.5f;
                        if (wSrc < 0.0f) { wSrc = 0.0f; }
                    }
                    int64_t w0 = static_cast<int64_t>(wSrc);
                    int64_t w1 = w0 + 1;
                    if (w1 >= iW_) { w1 = iW_ - 1; }
                    if (w0 >= iW_) { w0 = iW_ - 1; }
                    if (w0 < 0) { w0 = 0; }
                    float lw = (w0 != w1) ? (wSrc - static_cast<float>(w0)) : 0.0f;

                    float hlw = 1.0f - lw;
                    float w000 = wD0H0 * hlw;
                    float w001 = wD0H0 * lw;
                    float w010 = wD0H1 * hlw;
                    float w011 = wD0H1 * lw;
                    float w100 = wD1H0 * hlw;
                    float w101 = wD1H0 * lw;
                    float w110 = wD1H1 * hlw;
                    float w111 = wD1H1 * lw;

                    // Load single grad_output element from GM to UB
                    AscendC::LocalTensor<T> gradLocal = inQueue_.AllocTensor<T>();
                    AscendC::DataCopyExtParams copyParams = {1, sizeof(T), 0, 0, 0};
                    AscendC::DataCopyPadExtParams<T> padParams = {false, 0, 0, 0};
                    AscendC::DataCopyPad(gradLocal,
                        gradOutputGm_[gradOutputRowBase + wOut],
                        copyParams, padParams);
                    inQueue_.EnQue(gradLocal);
                    AscendC::LocalTensor<T> gradDeque = inQueue_.DeQue<T>();

                    // Get gradient value as float
                    float gradVal;
                    if constexpr (std::is_same_v<T, float>) {
                        gradVal = gradDeque.GetValue(0);
                    } else {
                        AscendC::LocalTensor<float> fp32Local = scatterFp32Buf_.Get<float>(1);
                        AscendC::Cast(fp32Local, gradDeque, AscendC::RoundMode::CAST_NONE, 1);
                        gradVal = fp32Local.GetValue(0);
                    }
                    inQueue_.FreeTensor(gradDeque);

                    // Scatter-add to 8 corners (GM read-modify-write)
                    ScatterAdd(gradInputSliceBase, d0, h0, w0, gradVal * w000);
                    ScatterAdd(gradInputSliceBase, d0, h0, w1, gradVal * w001);
                    ScatterAdd(gradInputSliceBase, d0, h1, w0, gradVal * w010);
                    ScatterAdd(gradInputSliceBase, d0, h1, w1, gradVal * w011);
                    ScatterAdd(gradInputSliceBase, d1, h0, w0, gradVal * w100);
                    ScatterAdd(gradInputSliceBase, d1, h0, w1, gradVal * w101);
                    ScatterAdd(gradInputSliceBase, d1, h1, w0, gradVal * w110);
                    ScatterAdd(gradInputSliceBase, d1, h1, w1, gradVal * w111);
                }
            }
        }
    }

    __aicore__ inline void ScatterAdd(
        int64_t gradInputBase, int64_t d, int64_t h, int64_t w, float value)
    {
        if (value == 0.0f) { return; }

        int64_t offset = gradInputBase + d * iH_ * iW_ + h * iW_ + w;

        AscendC::LocalTensor<T> scatterT = scatterTBuf_.Get<T>(1);
        AscendC::DataCopyExtParams copyParams = {1, sizeof(T), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParams = {false, 0, 0, 0};

        // Read current value from GM
        AscendC::DataCopyPad(scatterT, gradInputGm_[offset], copyParams, padParams);

        // Cast to float, add, cast back
        float currentVal;
        if constexpr (std::is_same_v<T, float>) {
            currentVal = scatterT.GetValue(0);
        } else {
            AscendC::LocalTensor<float> fp32Local = scatterFp32Buf_.Get<float>(1);
            AscendC::Cast(fp32Local, scatterT, AscendC::RoundMode::CAST_NONE, 1);
            currentVal = fp32Local.GetValue(0);
        }

        currentVal += value;
        AscendC::LocalTensor<float> fp32Local = scatterFp32Buf_.Get<float>(1);
        fp32Local.SetValue(0, currentVal);

        if constexpr (std::is_same_v<T, float>) {
            AscendC::DataCopyPad(gradInputGm_[offset], fp32Local, copyParams);
        } else {
            AscendC::Cast(scatterT, fp32Local, AscendC::RoundMode::CAST_ROUND, 1);
            AscendC::DataCopyPad(gradInputGm_[offset], scatterT, copyParams);
        }
    }

private:
    AscendC::TPipe pipe_;
    AscendC::GlobalTensor<T> gradOutputGm_;
    AscendC::GlobalTensor<T> gradInputGm_;

    AscendC::TQue<AscendC::QuePosition::VECIN, 2> inQueue_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> scatterFp32Buf_;
    AscendC::TBuf<AscendC::QuePosition::VECCALC> scatterTBuf_;

    float scaleD_, scaleH_, scaleW_;
    float scaleDNonAlign_, scaleHNonAlign_, scaleWNonAlign_;
    int64_t N_, C_, oD_, oH_, oW_, iD_, iH_, iW_;
    int64_t totalWorkItems_, tasksPerCore_;
    int64_t alignCorners_;
};

