#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_upsample_trilinear3d_backward.h"

namespace ascend_kernel {

at::Tensor upsample_trilinear3d_backward(
    const at::Tensor &grad_output,
    const at::Tensor &output_size,
    const at::Tensor &input_size,
    bool align_corners,
    double scale_d,
    double scale_h,
    double scale_w)
{
    TORCH_CHECK(grad_output.dim() == 5, "grad_output must be [N, C, oD, oH, oW]");
    TORCH_CHECK(
        grad_output.scalar_type() == at::kFloat ||
        grad_output.scalar_type() == at::kHalf ||
        grad_output.scalar_type() == at::kBFloat16,
        "grad_output must be float16, float32, or bfloat16");
    TORCH_CHECK(grad_output.is_contiguous(), "grad_output must be contiguous");

    int64_t N = grad_output.sizes()[0];
    int64_t C = grad_output.sizes()[1];
    int64_t oD = grad_output.sizes()[2];
    int64_t oH = grad_output.sizes()[3];
    int64_t oW = grad_output.sizes()[4];

    // input_size and output_size may be on NPU; copy to CPU for host access
    at::Tensor input_size_cpu = input_size.to(at::kCPU);
    at::Tensor output_size_cpu = output_size.to(at::kCPU);

    TORCH_CHECK(input_size_cpu.numel() == 5,
        "input_size must be [N, C, iD, iH, iW] with 5 elements");
    TORCH_CHECK(output_size_cpu.numel() == 5,
        "output_size must be [N, C, oD, oH, oW] with 5 elements");

    int64_t *inputSizeData = input_size_cpu.data_ptr<int64_t>();
    int64_t iN = inputSizeData[0];
    int64_t iC = inputSizeData[1];
    int64_t iD = inputSizeData[2];
    int64_t iH = inputSizeData[3];
    int64_t iW = inputSizeData[4];

    // Create output tensor on the same device as input
    at::Tensor grad_input = at::zeros({iN, iC, iD, iH, iW}, grad_output.options());

    // Compute scale factors
    float scaleDVal = 0.0f;
    float scaleHVal = 0.0f;
    float scaleWVal = 0.0f;
    float scaleDNonAlignVal = 0.0f;
    float scaleHNonAlignVal = 0.0f;
    float scaleWNonAlignVal = 0.0f;

    if (align_corners) {
        if (oD > 1) { scaleDVal = static_cast<float>(iD - 1) / static_cast<float>(oD - 1); }
        if (oH > 1) { scaleHVal = static_cast<float>(iH - 1) / static_cast<float>(oH - 1); }
        if (oW > 1) { scaleWVal = static_cast<float>(iW - 1) / static_cast<float>(oW - 1); }
    } else {
        if (scale_d > 0.0) {
            scaleDNonAlignVal = static_cast<float>(scale_d);
        } else if (oD != 0) {
            scaleDNonAlignVal = static_cast<float>(iD) / static_cast<float>(oD);
        }
        if (scale_h > 0.0) {
            scaleHNonAlignVal = static_cast<float>(scale_h);
        } else if (oH != 0) {
            scaleHNonAlignVal = static_cast<float>(iH) / static_cast<float>(oH);
        }
        if (scale_w > 0.0) {
            scaleWNonAlignVal = static_cast<float>(scale_w);
        } else if (oW != 0) {
            scaleWNonAlignVal = static_cast<float>(iW) / static_cast<float>(oW);
        }
    }

    // Tiling: block level
    int64_t totalWorkItems = N * C;

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendcPlatform->GetCoreNumAiv());
    int64_t usedCoreNum = std::min<int64_t>(coreNum, std::max<int64_t>(1, totalWorkItems));
    int64_t tasksPerCore = (totalWorkItems + usedCoreNum - 1) / usedCoreNum;

    // All left values for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    int32_t N32 = static_cast<int32_t>(N);
    int32_t C32 = static_cast<int32_t>(C);
    int32_t oD32 = static_cast<int32_t>(oD);
    int32_t oH32 = static_cast<int32_t>(oH);
    int32_t oW32 = static_cast<int32_t>(oW);
    int32_t iD32 = static_cast<int32_t>(iD);
    int32_t iH32 = static_cast<int32_t>(iH);
    int32_t iW32 = static_cast<int32_t>(iW);
    int32_t totalWorkItems32 = static_cast<int32_t>(totalWorkItems);
    int32_t tasksPerCore32 = static_cast<int32_t>(tasksPerCore);
    int32_t alignCornersInt32 = static_cast<int32_t>(align_corners);
    int64_t dtypeFlag = 0;
    if (grad_output.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (grad_output.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    EXEC_KERNEL_CMD(upsample_trilinear3d_backward, blockDim,
                    grad_output, grad_input,
                    scaleDVal, scaleHVal, scaleWVal,
                    scaleDNonAlignVal, scaleHNonAlignVal, scaleWNonAlignVal,
                    N32, C32, oD32, oH32, oW32,
                    iD32, iH32, iW32,
                    totalWorkItems32, tasksPerCore32,
                    alignCornersInt32,
                    dtypeFlag);

    return grad_input;
}

}  // namespace ascend_kernel
